/* Fixed UTC offset for AGENT_TIMEZONE ("CST-8" = UTC+8).
 * NuttX romfs lacks zoneinfo, so localtime_r()/mktime() are avoided;
 * we apply the offset manually as done in tool_get_time.c. */
#define CRON_TZ_OFFSET_SEC (8 * 3600)

static int64_t cron_daily_next_epoch(uint8_t hour, uint8_t minute)
{
    time_t now = time(NULL);
    time_t local_now = now + CRON_TZ_OFFSET_SEC;
    struct tm lt;
    gmtime_r(&local_now, &lt);

    int target = (int)hour * 3600 + (int)minute * 60;
    int current = lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec;
    int delta = target - current;
    if (delta <= 0) {
        delta += 86400;
    }

    time_t local_next = local_now + delta;
    return (int64_t)(local_next - CRON_TZ_OFFSET_SEC);
}
```
