3. Helper to compute next occurrence epoch for daily.

Need offset. AGENT_TIMEZONE is "CST-8". The convention: local_epoch = now + 8*3600; gmtime_r(&local_epoch, &local) gives local Y/M/D/H/M/S. Compute seconds until target local hour:minute. If <=0 add 86400. Return epoch in UTC = target_local_epoch - offset.

Implementation:
```c
/* Fixed local timezone offset (seconds east of UTC).
 * AGENT_TIMEZONE is "CST-8" (POSIX TZ: UTC+8), so local = UTC + 8h.
 * We deliberately avoid localtime_r()/mktime() because NuttX's
 * zoneinfo lookup fails for POSIX TZ strings on romfs. */
#define CRON_TZ_OFFSET_SEC (8 * 3600)

static time_t cron_daily_next_epoch(uint8_t hour, uint8_t min, time_t now)
{
    time_t local_now = now + CRON_TZ_OFFSET_SEC;
    struct tm local_tm;

    if (!gmtime_r(&local_now, &local_tm)) {
        return now + 86400;  /* fallback: retry in a day */
    }

    /* Seconds elapsed since local midnight */
    time_t local_midnight = local_now
        - (local_tm.tm_hour * 3600 + local_tm.tm_min * 60 + local_tm.tm_sec);

    time_t target_local = local_midnight + (time_t)hour * 3600 + (time_t)min * 60;

    if (target_local <= local_now) {
        target_local += 86400;
    }

    return target_local - CRON_TZ_OFFSET_SEC;
}
```

