```c
#define NET_STATUS_FILE AGENT_DATA_DIR "/NET_STATUS"

static void net_status_write_file(net_state_t state)
{
    const char* path = NET_STATUS_FILE;
    FILE* f = fopen(path, "w");
    if (!f) {
        syslog(LOG_DEBUG, "[%s] Cannot write %s (errno=%d)\n", TAG, path, errno);
        return;
    }

    if (state == NET_STATE_CONNECTED) {
        const char* ip = g_net_status.ip_addr[0] ? g_net_status.ip_addr : "0.0.0.0";
        fprintf(f, "CONNECTED %s\n", ip);
    } else {
        fprintf(f, "DISCONNECTED\n");
    }

    fclose(f);
}

static void net_status_file_listener(net_state_t state, void* arg)
{
    (void)arg;
    net_status_write_file(state);
}
```

