/* ── Network status file (for external UI process) ────────────── */

/* The LVGL UI runs in a separate process and cannot call
 * network_is_connected() directly, so we mirror the connection
 * state into a small file it can poll. */
static void net_status_file_listener(net_state_t state, void* arg)
{
    (void)arg;

    const char* path = AGENT_DATA_DIR "/NET_STATUS";
    FILE* fp = fopen(path, "w");

    if (!fp) {
        syslog(LOG_DEBUG, "[%s] Cannot write %s: %d\n", TAG, path, errno);
        return;
    }

    if (state == NET_STATE_CONNECTED) {
        const char* ip = g_net_status.ip_addr[0] ? g_net_status.ip_addr : "0.0.0.0";
        fprintf(fp, "CONNECTED %s\n", ip);
    } else {
        fprintf(fp, "DISCONNECTED\n");
    }

    fclose(fp);
}
