```c
/* ── Network status file for UI consumption ───────────────────── */
/* The LVGL UI runs in a separate task/process and cannot call
 * network_is_connected() directly, so mirror the current state to
 * AGENT_DATA_DIR "/NET_STATUS" whenever it changes.  The UI polls
 * this single-line file:
 *   CONNECTED <ip>\n
 *   DISCONNECTED\n
 * File I/O failures are non-fatal (logged at debug level only). */

#define NET_STATUS_FILE AGENT_DATA_DIR "/NET_STATUS"

static int write_net_status_file(net_state_t state)
{
    FILE* f = fopen(NET_STATUS_FILE, "w");
    if (!f) {
        syslog(LOG_DEBUG, "[%s] Cannot write %s: %d\n", TAG, NET_STATUS_FILE, errno);
        return ERROR;
    }

    if (state == NET_STATE_CONNECTED) {
        fprintf(f, "CONNECTED %s\n", g_net_status.ip_addr);
    } else {
        fprintf(f, "DISCONNECTED\n");
    }

    fclose(f);
    return OK;
}

static void net_status_file_cb(net_state_t state, void* arg)
{
    (void)arg;
    write_net_status_file(state);
}
```

