```c
/* Compute the next UTC epoch at which a daily job should fire.
 *
 * NuttX romfs lacks zoneinfo, so localtime_r()/mktime() cannot be used
 * (see tool_get_time.c).  Instead we apply the fixed AGENT_TIMEZONE
 * ("CST-8", UTC+8) offset manually: shift the UTC clock forward by the
 * offset, read the local Y/M/D/H/M/S with gmtime_r(), compute the
 * seconds until the target local hour:minute, and shift the resulting
 * epoch back to UTC.  If the target time has already passed today
 * (delta <= 0), schedule it for the same time tomorrow.
 *
 * NOTE: this assumes a fixed UTC+8 offset (AGENT_TIMEZONE "CST-8");
 * it does not track DST, which is correct for China. */
#define AGENT_TIMEZONE_OFFSET_SEC (8 * 3600)

static int64_t cron_daily_next_epoch(uint8_t hour, uint8_t minute)
{
    time_t now = time(NULL);
    struct tm local;

    /* Convert to local wall-clock via fixed offset (no zoneinfo). */
    time_t local_now = now + AGENT_TIMEZONE_OFFSET_SEC;
    gmtime_r(&local_now, &local);

    int64_t delta = (int64_t)hour * 3600 + (int64_t)minute * 60
        - ((int64_t)local.tm_hour * 3600 + (int64_t)local.tm_min * 60
            + (int64_t)local.tm_sec);

    if (delta <= 0) {
        delta += 86400; /* already passed today — fire tomorrow */
    }

    /* local_now rounded back to the top of the current local minute is
     * not needed; delta is measured from "now", so add it directly. */
    return (int64_t)now + delta;
}
```

