/* Fixed local timezone offset in seconds. AGENT_TIMEZONE is "CST-8"
 * (UTC+8); NuttX romfs lacks zoneinfo, so we hard-code the offset as
 * done in tool_get_time.c instead of calling localtime_r/mktime. */
#define CRON_TZ_OFFSET_SEC (8 * 3600)

static int64_t cron_next_daily_epoch(uint8_t hour, uint8_t min, time_t now)
{
    time_t local_now = now + CRON_TZ_OFFSET_SEC;
    struct tm tmv;
    gmtime_r(&local_now, &tmv);

    long sec_of_day = (long)tmv.tm_hour * 3600 + tmv.tm_min * 60 + tmv.tm_sec;
    long target = (long)hour * 3600 + (long)min * 60;
    long delta = target - sec_of_day;

    if (delta <= 0) {
        delta += 86400;
    }

    return (int64_t)(now + delta);
}
