```c
/* Timezone assumption: AGENT_TIMEZONE is "CST-8" (UTC+8), so local time
 * is UTC + 8 hours.  We deliberately avoid localtime_r()/mktime() because
 * NuttX's romfs zoneinfo lookup fails for POSIX TZ strings like "CST-8"
 * (see tool_get_time.c).  Instead we shift the epoch by a fixed offset,
 * use gmtime_r() to read local Y/M/D/H/M/S, and shift back. */
#define CRON_TZ_OFFSET_SEC (8 * 3600)

static int64_t cron_daily_next_epoch(uint8_t hour, uint8_t min)
{
    time_t now = time(NULL);
    time_t local_now = now + CRON_TZ_OFFSET_SEC;
    struct tm tm_local;
    gmtime_r(&local_now, &tm_local);

    int secs_today = tm_local.tm_hour * 3600 + tm_local.tm_min * 60
        + tm_local.tm_sec;
    int secs_target = (int)hour * 3600 + (int)min * 60;
    int delta = secs_target - secs_today;

    if (delta <= 0) {
        delta += 86400;
    }

    return (int64_t)(now + delta);
}
