**Helper: next daily occurrence**

```c
/* Timezone offset used by the agent.  AGENT_TIMEZONE is a POSIX TZ
 * string ("CST-8"), i.e. UTC+8.  NuttX romfs has no zoneinfo database,
 * so localtime_r()/mktime() must be avoided (see tool_get_time.c).
 * We therefore compute local time as UTC + AGENT_TZ_OFFSET_SEC. */
#define AGENT_TZ_OFFSET_SEC (8 * 3600)

/* Compute the next epoch at which a daily job should fire.
 * Returns the epoch in UTC.  The comparison "<= now" means that if
 * today's target time has already passed (or is exactly now), the job
 * is scheduled for the same local time tomorrow. */
static int64_t cron_daily_next_run(uint8_t hour, uint8_t min)
{
    time_t now = time(NULL);

    /* Convert "now" to local wall-clock time via gmtime_r(). */
    time_t local_now = now + AGENT_TZ_OFFSET_SEC;
    struct tm tm_local;
    gmtime_r(&local_now, &tm_local);

    /* Seconds elapsed today in local time. */
    int64_t elapsed = (int64_t)tm_local.tm_hour * 3600
        + (int64_t)tm_local.tm_min * 60
        + (int64_t)tm_local.tm_sec;
    int64_t target = (int64_t)hour * 3600 + (int64_t)min * 60;

    int64_t delta = target - elapsed;

    if (delta <= 0) {
        delta += 86400;
    }

    /* delta is relative to local now; convert back to UTC epoch. */
    return (int64_t)now + delta;
}
```

