```c
/* ── Network status file for the UI process ───────────────────── */
/* The LVGL UI runs in a separate process and cannot call
 * network_is_connected(), so we mirror the latest state into
 * AGENT_DATA_DIR/NET_STATUS for it to poll.  Format is a single line:
 *   "CONNECTED <ip>\n"  or  "DISCONNECTED\n".
 *
 * NOTE: this is invoked from notify_listeners() with g_net_mutex held,
 * so it must not take that mutex again (it would deadlock). */

#define NET_STATUS_FILE AGENT_DATA_DIR "/NET_STATUS"

static void net_status_file_write(net_state_t state)
{
    FILE* f = fopen(NET_STATUS_FILE, "w");

    if (!f) {
        /* Data dir may not exist yet; never fatal. */
        syslog(LOG_DEBUG, "[%s] Cannot write %s: %d\n",
            TAG, NET_STATUS_FILE, errno);
        return;
    }

    if (state == NET_STATE_CONNECTED) {
        fprintf(f, "CONNECTED %s\n",
            g_net_status.ip_addr[0] ? g_net_status.ip_addr : "0.0.0.0");
    } else {
        fprintf(f, "DISCONNECTED\n");
    }

    fclose(f);
}

static void net_status_listener(net_state_t state, void* arg)
{
    (void)arg;
    net_status_file_write(state);
}
