```c
/* Fixed UTC offset (seconds) for AGENT_TIMEZONE ("CST-8" == UTC+8).
 * This codebase avoids localtime_r()/mktime() because NuttX's romfs
 * zoneinfo lookup fails for POSIX TZ strings; we therefore apply the
 * offset manually, exactly as tool_get_time.c does. */
#define CRON_TZ_OFFSET_SEC (8 * 3600)

/* Compute the next epoch at which a daily job should fire.
 * Local time is derived via gmtime_r(now + CRON_TZ_OFFSET_SEC); the
 * returned value is a real UTC epoch. */
static int64_t cron_next_daily_run(uint8_t hour, uint8_t min, time_t now)
{
    struct tm local;
    time_t local_now = now + CRON_TZ_OFFSET_SEC;
    gmtime_r(&local_now, &local);

    int cur = local.tm_hour * 3600 + local.tm_min * 60 + local.tm_sec;
    int target = (int)hour * 3600 + (int)min * 60;

    long delta = (long)target - cur;
    if (delta <= 0) {
        delta += 86400;
    }

    /* Convert the local next-run back to a UTC epoch. */
    return (int64_t)(local_now + delta - CRON_TZ_OFFSET_SEC);
}
```

